(function(raiz){var HORAS_MES_JORNADA=160;var SEMANAS_MES=52/12;var TAREAS=[["leads","Log leads in the CRM and send the first reply","Meta leads land in the CRM on their own and the AI setter replies on WhatsApp","solo",10],["contratos","Draft contracts and chase signatures","The contract is built from the deal in three languages, and signature reminders and expiry run on their own","prepara",8],["facturas","Issue invoices and receipts","Each invoice comes from the contract and the milestone that is due","prepara",6],["cobros","Keep the payment schedule","Paid and outstanding amounts are worked out from the receipts, not by hand","solo",6],["comisiones","Calculate commissions","The commission is generated from the sale","solo",4]];var DEFECTO={coste:2500,pct:50};function num(v,min,max){var n=typeof v==="number"?v:parseFloat(String(v).replace(",","."));if(!isFinite(n))n=0;return Math.min(max,Math.max(min,n))}function calcula(horas,coste,pct){var semana=0,usadas={};TAREAS.forEach((function(t){usadas[t[0]]=num(horas&&horas[t[0]],0,168);semana+=usadas[t[0]]}));var c=num(coste,0,1e12),p=num(pct,0,100)/100;var horasMes=semana*SEMANAS_MES*p;var puestos=horasMes/HORAS_MES_JORNADA;return{entrada:{horas:usadas,coste:c,pct:p*100},horasSemanaEquipo:semana,horasMes:horasMes,puestos:puestos,valorMes:puestos*c,valorAno:puestos*c*12}}function frasePuestos(p){var horasSemana=p*HORAS_MES_JORNADA/SEMANAS_MES;if(horasSemana<.5)return"nothing yet";if(p<.4)return"about "+Math.round(horasSemana).toLocaleString("en-GB")+" h a week of one person";if(p<.65)return"half a full-time person";if(p<.9)return"almost one full-time person";if(p<1.15)return"one full-time person";return"about "+(Math.round(p*2)/2).toLocaleString("en-GB")+" full-time people"}var api={TAREAS:TAREAS,DEFECTO:DEFECTO,HORAS_MES_JORNADA:HORAS_MES_JORNADA,SEMANAS_MES:SEMANAS_MES,calcula:calcula,frasePuestos:frasePuestos};if(typeof module!=="undefined"&&module.exports)module.exports=api;else raiz.AXW_ROI=api})(this);